<?php
namespace App\Domain\Products; use App\Domain\Homepage\HomepageCache;use App\Domain\PublicChrome\PublicChromeCache;use App\Models\{HomepageItem,NavigationItem};use Illuminate\Support\Facades\Cache;use Throwable;
final class ProductCache {public static function version(int $id):int{try{return (int)Cache::rememberForever("public.products.version.$id",fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}}public static function indexVersion():int{try{return (int)Cache::rememberForever('public.products.index.version',fn()=>hrtime(true));}catch(Throwable){return hrtime(true);}}public static function forget(int $id):void{try{Cache::put("public.products.version.$id",hrtime(true));Cache::put('public.products.index.version',hrtime(true));if(HomepageItem::where('product_id',$id)->exists())HomepageCache::forget();if(NavigationItem::where('product_id',$id)->exists())PublicChromeCache::forgetAll();}catch(Throwable){}}}